#include <unordered_set>
#include <vector>

std::vector<int> remove_duplicates(const std::vector<int>& values) {
    std::unordered_set<int> seen;
    std::vector<int> result;
    for (int v : values) {
        if (seen.insert(v).second)
            result.push_back(v);
    }
    return result;
}

