template <typename T>
std::pair<std::vector<T>, std::vector<T>>
partition_by(const std::vector<T>& v, std::function<bool(const T&)> pred) {
    std::vector<T> yes, no;
    for (const auto& x : v)
        (pred(x) ? yes : no).push_back(x);
    return {yes, no};
}
